package com.lianxibu.site.service.sources;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.repository.sources.*;import com.lianxibu.site.repository.identity.JdbcNodeStore;import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;import com.lianxibu.site.service.jobs.SharedWriteExecutor;import com.lianxibu.site.service.identity.NodeIdentityService;
import java.time.*;import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;import org.h2.jdbcx.JdbcDataSource;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.junit.jupiter.api.*;
class SourceContractSnapshotServiceTest {
 SourceContractSnapshotsTest f;SourceContractSnapshotService service;String sourceId,nodeId,token;Clock clock;JdbcNodeStore nodes;JdbcSourceAdmission sources;
 DataSource source(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:source-health-service-"+System.nanoTime()+";DB_CLOSE_DELAY=-1;MODE=MySQL");return ds;}
 @BeforeEach void setup(){f=new SourceContractSnapshotsTest(){@Override DataSource source(){return SourceContractSnapshotServiceTest.this.source();}};f.setup();boolean h2=f.db instanceof JdbcDataSource;String json=h2?"CLOB":"JSON",time=h2?"TIMESTAMP(6)":"DATETIME(6)";f.jdbc.execute("CREATE TABLE IF NOT EXISTS worker_lock(id INT PRIMARY KEY)");if(f.jdbc.queryForObject("SELECT COUNT(*) FROM worker_lock WHERE id=1",Integer.class)==0)f.jdbc.update("INSERT INTO worker_lock(id) VALUES(1)");f.jdbc.execute("CREATE TABLE IF NOT EXISTS sources(id VARCHAR(80) PRIMARY KEY,source_kind VARCHAR(32),name VARCHAR(200),state VARCHAR(32),config_json "+json+",probe_json "+json+",draft_config_json "+json+",effective_config_json "+json+",revision BIGINT,updated_at "+time+",config_revision BIGINT,activation_stage VARCHAR(32),config_valid_until "+time+",category VARCHAR(32))");f.jdbc.execute("CREATE TABLE IF NOT EXISTS collector_nodes(id VARCHAR(64) PRIMARY KEY,name VARCHAR(100),token_hash BINARY(32) UNIQUE,allowed_source_ids "+json+",permissions_json "+json+",enabled INT,last_seen_at "+time+",config_revision BIGINT)");if(!h2)for(var column:Map.of("probe_json","JSON","updated_at","DATETIME(6)").entrySet())if(f.jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='sources' AND column_name=?",Integer.class,column.getKey())==0)f.jdbc.execute("ALTER TABLE sources ADD COLUMN "+column.getKey()+" "+column.getValue()+" NULL");sourceId=UUID.randomUUID().toString();nodeId=UUID.randomUUID().toString();clock=Clock.fixed(f.now,ZoneOffset.UTC);sources=new JdbcSourceAdmission(f.db);f.tx.execute(s->{sources.create(sourceId,"rss","Fictional snapshot source","news_tech","{}",f.now);assertTrue(sources.setManualProduction(sources.locked(sourceId),f.now.plusSeconds(3600),f.now));return null;});var key=new NodeTokens(new byte[32]);token=key.issue("fictional-owner","fictional-health","fictional-health-key",nodeId);nodes=new JdbcNodeStore(f.db);nodes.create(nodeId,"Fictional telemetry node",NodeTokens.digest(token),"[\""+sourceId+"\"]","[\"heartbeat:write\"]");var identity=new NodeIdentityService(nodes,key,clock);var writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(f.db),new DataSourceTransactionManager(f.db));service=new SourceContractSnapshotService(f.store,sources,identity,writes,clock);}
 @AfterEach void cleanup(){if(f!=null&&sourceId!=null)f.jdbc.update("DELETE FROM sources WHERE id=?",sourceId);if(f!=null&&nodeId!=null)f.jdbc.update("DELETE FROM collector_nodes WHERE id=?",nodeId);}
 byte[] raw(long sequence)throws Exception{var root=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(f.value(sequence,1,true).canonical());root.put("source_id",sourceId);return CanonicalJson.bytes(root);}
 @Test void actualNodeAndCurrentSourceUseOriginalSharedWriterAndReplayAfterConfigChanges()throws Exception{var body=raw(1);var result=service.submit(token,sourceId,body);assertNotNull(result);assertEquals(nodeId,result.nodeId());assertEquals(1,result.nodeRevision());assertEquals(result,service.submit(token,sourceId,body));f.jdbc.update("UPDATE sources SET config_revision=config_revision+1,activation_stage='disabled' WHERE id=?",sourceId);assertEquals(result,service.submit(token,sourceId,body));var error=assertThrows(SourceContractSnapshotService.Rejected.class,()->service.submit(token,sourceId,raw(2)));assertEquals("stale_config",error.code());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));}
 @Test void revocationTokenRotationOrRemovedScopePreventsEvenCachedAck()throws Exception{var body=raw(1);service.submit(token,sourceId,body);assertEquals(1,nodes.revoke(nodeId,1));assertThrows(com.lianxibu.site.service.identity.IdentityService.Rejected.class,()->service.submit(token,sourceId,body));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));}
 @Test void wrongSourceOrCurrentPermissionAndVersionNeverWritesHealth()throws Exception{assertThrows(SourceContractSnapshotService.Rejected.class,()->service.submit(token,"fictional-other",raw(1)));assertEquals(1,nodes.setPermissions(nodeId,1,"[]","[\"heartbeat:write\"]"));assertThrows(com.lianxibu.site.service.identity.IdentityService.Rejected.class,()->service.submit(token,sourceId,raw(1)));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));}
 @Test void completeFailureReceiptAndPointerCommitOnceUnderConcurrentRequests()throws Exception{var body=raw(1);var pool=Executors.newFixedThreadPool(2);try{var latch=new CountDownLatch(1);Callable<JdbcSourceContractSnapshots.Receipt> task=()->{assertTrue(latch.await(5,TimeUnit.SECONDS));return service.submit(token,sourceId,body);};var first=pool.submit(task);var second=pool.submit(task);latch.countDown();assertEquals(first.get(10,TimeUnit.SECONDS),second.get(10,TimeUnit.SECONDS));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM runtime_settings",Integer.class));}finally{pool.shutdownNow();}}
 @Test void anOuterTransactionOrFutureReportedFactCannotCommit()throws Exception{var body=raw(1);assertThrows(IllegalStateException.class,()->f.tx.execute(s->service.submit(token,sourceId,body)));var root=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(body);root.put("observed_at","2026-01-01T00:10:01.000000Z");root.put("window_start","2026-01-01T00:00:01.000000Z");assertThrows(IllegalStateException.class,()->service.submit(token,sourceId,CanonicalJson.bytes(root)));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));}
}
